const PREFIXES: [&str; 2] = ["/soqrates", "/socrates"];

/// `first` is the first word of a comment.
fn is_addressed(first: &str, app_slug: &str) -> bool {
    let by_prefix = PREFIXES
        .iter()
        .any(|p| first.eq_ignore_ascii_case(p));
    let by_mention = first.eq_ignore_ascii_case(&format!("@{app_slug}"));
    by_prefix || by_mention
}

// The app that posts the comments may be registered as
// slug "soqrates", "soqrates-review", or anything else.
